export function buildStocksSchedule(startISO = null) {
  return buildScheduleFor(STOCKS_MODULES, startISO, STOCKS_META.cadenceDays);
}

export function stocksProgressSummary(progress = {}) {
  return progressSummaryFor(STOCKS_MODULES, progress);
}

export function exportStocksCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: STOCKS_META,
    modules: buildStocksSchedule(startISO),
    sessionFlow: STOCKS_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function stocksRefs() {
  const seen = new Set();
  for (const m of STOCKS_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((STOCKS_META.wordFirst && STOCKS_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

